def target_sum_ways(nums, target):
    ways = {0: 1}
    for x in nums:
        new = {}
        for s, c in ways.items():
            new[s + x] = new.get(s + x, 0) + c
            new[s - x] = new.get(s - x, 0) + c
        ways = new
    return ways.get(target, 0)
